package com.checkon.engagement.presentation;
import org.springframework.http.*;import org.springframework.http.converter.HttpMessageNotReadableException;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;import com.checkon.engagement.application.EngagementException;
@RestControllerAdvice(assignableTypes=EngagementController.class) public class EngagementExceptionHandler {
 @ExceptionHandler({MethodArgumentNotValidException.class,HttpMessageNotReadableException.class,MethodArgumentTypeMismatchException.class}) ResponseEntity<ErrorResponse> invalid(){return response(HttpStatus.BAD_REQUEST,"INVALID_REQUEST","요청 값을 확인해 주세요.");}
 @ExceptionHandler(EngagementException.class) ResponseEntity<ErrorResponse> failure(EngagementException e){return switch(e.reason()){case INVALID_PRINCIPAL->response(HttpStatus.UNAUTHORIZED,"INVALID_TEACHER_PRINCIPAL","유효한 강사 인증 정보가 필요합니다.");case NOT_FOUND->response(HttpStatus.NOT_FOUND,"ENGAGEMENT_RESOURCE_NOT_FOUND","대상을 찾을 수 없습니다.");case INVALID_STATE->response(HttpStatus.CONFLICT,"INVALID_ENGAGEMENT_STATE","현재 상태에서는 요청을 처리할 수 없습니다.");case ACTIVE_REMINDER_EXISTS->response(HttpStatus.CONFLICT,"ACTIVE_REMINDER_EXISTS","이미 활성 리마인드가 있습니다.");case INVALID_REQUEST->response(HttpStatus.BAD_REQUEST,"INVALID_REQUEST","요청 값을 확인해 주세요.");};}
 private ResponseEntity<ErrorResponse> response(HttpStatus s,String c,String m){return ResponseEntity.status(s).body(new ErrorResponse(c,m));}public record ErrorResponse(String code,String message){}
}
